// public List<RateTableZoneEntity> AccountDetailsEntities { get; set; }
// public List<ShipperEntity>   Shippers       { get; set; }
// …etc…

// Tell AutoMapper how to map the entity → dto classes 1:1
CreateMap<RateTableZoneEntity, ZoneDto>().ReverseMap();
CreateMap<ConsigneeEntity, ConsigneeDto>().ReverseMap();
CreateMap<ShipperEntity,  ShipperDto>().ReverseMap();

// And now:
CreateMap<CustomerEntity, CustomerAccountDto>()
  .ForMember(dest => dest.Consignees,
             opt => opt.MapFrom(src => src.AccountDetailsEntities))
  .ForMember(dest => dest.Shippers,
             opt => opt.MapFrom(src => src.Shippers))
  // …any other list props…
  ;
```

No JSON, no serializers, no resolvers at all.  If your entity property is already a `List<SomeEntity>`, you don’t need to serialize anything—you can just let AutoMapper traverse it.

---

Pick the approach that matches how you’re persisting your data:

- **JSON‐in‐a‐string‐column** → use a `string` property on your EF class + custom resolvers.  
- **Relational child tables** → use `List<ChildEntity>` navigation props + pure AutoMapper maps.

